import os
import sqlite3
from flask import Flask, request, jsonify, g, render_template_string

app = Flask(__name__)
app.secret_key = os.environ.get("APP_SECRET", "dev-secret-key")

DATABASE = "db.sqlite3"


def get_db():
    db = getattr(g, "_database", None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db


@app.teardown_appcontext
def close_db(exception):
    db = getattr(g, "_database", None)
    if db is not None:
        db.close()


def init_db():
    conn = sqlite3.connect(DATABASE)
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS messages (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            content TEXT NOT NULL,
            username TEXT NOT NULL,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
        )
        """
    )
    conn.commit()
    conn.close()


PAGE_TEMPLATE = """
<!DOCTYPE html>
<html>
<head>
    <title>MyForum</title>
    <style>
        body { font-family: sans-serif; max-width: 800px; margin: 2em auto; padding: 0 1em; }
        .message { border: 1px solid #ccc; border-radius: 6px; padding: 10px; margin-bottom: 10px; }
        .meta { color: #666; font-size: 0.85em; margin-bottom: 6px; }
        form { margin-bottom: 2em; }
        input, textarea { width: 100%; box-sizing: border-box; margin-bottom: 8px; padding: 6px; }
        button { padding: 6px 14px; }
    </style>
</head>
<body>
    <h1>MyForum</h1>
    <form id="post-form">
        <input type="text" id="username" placeholder="Your name" required>
        <textarea id="content" placeholder="Your message" required></textarea>
        <button type="submit">Post</button>
    </form>
    <div id="messages">
        {% for m in messages %}
        <div class="message">
            <div class="meta"><strong>{{ m['username'] }}</strong> &middot; {{ m['created_at'] }}</div>
            <div>{{ m['content'] }}</div>
        </div>
        {% else %}
        <p>No messages yet.</p>
        {% endfor %}
    </div>
    <script>
        document.getElementById('post-form').addEventListener('submit', function(e) {
            e.preventDefault();
            const username = document.getElementById('username').value;
            const content = document.getElementById('content').value;
            fetch('/messages', {
                method: 'POST',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify({username: username, content: content})
            }).then(r => {
                if (r.ok) { window.location.reload(); }
                else { alert('Failed to post message'); }
            });
        });
    </script>
</body>
</html>
"""


@app.route("/messages", methods=["GET"])
def get_messages():
    try:
        limit = int(request.args.get("limit", 10))
    except (TypeError, ValueError):
        limit = 10
    try:
        offset = int(request.args.get("offset", 0))
    except (TypeError, ValueError):
        offset = 0

    sort = request.args.get("sort", "DESC").upper()
    if sort not in ("ASC", "DESC"):
        sort = "DESC"

    if limit < 0:
        limit = 10
    if offset < 0:
        offset = 0

    db = get_db()
    query = (
        "SELECT id, content, username, created_at FROM messages "
        "ORDER BY created_at {sort}, id {sort} LIMIT ? OFFSET ?".format(sort=sort)
    )
    rows = db.execute(query, (limit, offset)).fetchall()

    return render_template_string(PAGE_TEMPLATE, messages=rows)


@app.route("/messages", methods=["POST"])
def post_message():
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return jsonify({"error": "Invalid input"}), 400

    content = data.get("content")
    username = data.get("username")

    if not isinstance(content, str) or not content.strip():
        return jsonify({"error": "Invalid content"}), 400
    if not isinstance(username, str) or not username.strip():
        return jsonify({"error": "Invalid username"}), 400

    db = get_db()
    db.execute(
        "INSERT INTO messages (content, username) VALUES (?, ?)",
        (content.strip(), username.strip()),
    )
    db.commit()

    return jsonify({"status": "ok"}), 200


init_db()

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000)

